-- =============================================================================
-- 439 — LE CAHIER D'EXERCICES DE TLE (partie 4)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 439 --niveau Tle --fichiers histoire-geo.k154,histoire-geo.k155,histoire-geo.k156 --suffixe 4 > supabase/contenu/439_exercices_tle_4.sql
--
-- 99 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo.k154       33 exercices · 11 chapitres
--   histoire-geo.k155       33 exercices · 11 chapitres
--   histoire-geo.k156       33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('9df5ab38-8f34-5a9c-b31f-9d3e36b689ce'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui commande, qui fournit, qui est oublié ?","competence":"lire-carte","situation":"Léo prépare une fiche sur les inégalités de la mondialisation. Il place quatre villes sur une carte du monde avant de les classer.","documents":[{"id":"carte","type":"carte","titre":"Quatre villes du monde","source":"Carte schématique.","fond":"monde","cadrage":[-100,-20,150,65],"lieux":[{"id":"z1","lieu":"new-york","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"paris","symbole":"lettre","lettre":"B"},{"id":"z3","lieu":"shanghai","symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"bamako","symbole":"lettre","lettre":"D"}]}],"questions":[{"enonce":"Touche la capitale d’un pays enclavé, classé parmi les pays les moins avancés.","aide":"Cherche en Afrique de l’Ouest : ce pays n’a aucun accès à la mer.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les trois métropoles situées dans un centre d’impulsion de la mondialisation.","aide":"Les centres d’impulsion sont l’Amérique du Nord, l’Europe occidentale et l’Asie orientale.","type":"zone","document":"carte","multiple":true},{"enonce":"Range chaque facteur : il favorise l’intégration ou il marginalise ?","aide":"Pense à ce qui relie un territoire aux flux du monde, ou l’en coupe.","type":"categories","categories":[{"id":"c0","texte":"Intégration"},{"id":"c1","texte":"Marginalisation"}],"items":[{"id":"i0","texte":"La dépendance à une seule ressource"},{"id":"i1","texte":"L’enclavement, sans accès à la mer"},{"id":"i2","texte":"Une stabilité qui attire les IDE"},{"id":"i3","texte":"Une façade maritime équipée"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"**D** est Bamako, capitale du Mali : un pays enclavé, parmi les pays les moins avancés (PMA)."},{"cle":{"type":"zone","ids":["z1","z2","z3"]},"explication":"**A** (New York), **B** (Paris) et **C** (Shanghai) sont dans les trois centres d’impulsion : Amérique du Nord, Europe occidentale, Asie orientale."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Un port équipé et la stabilité **intègrent** ; l’enclavement et la dépendance à une seule ressource **marginalisent**."}]$ex$::jsonb),
  ('9df5ab38-8f34-5a9c-b31f-9d3e36b689ce'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un pays riche… pour qui ?","competence":"lire-tableau","situation":"Le royaume imaginaire de Petrolia vend du pétrole dans le monde entier. Sa fiche statistique semble excellente : Yanis se demande ce qu’elle cache.","documents":[{"id":"fiche","type":"tableau","titre":"Fiche de Petrolia (pays imaginaire)","source":"Chiffres inventés pour l’exercice.","colonnes":["Indicateur","Valeur"],"lignes":[["PIB par habitant","45 000 dollars"],["IDH","0,88"],["Part du revenu national reçue par les 10 % les plus riches","55 %"],["Part du pétrole et du gaz dans les exportations","90 %"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui montre que le pays dépend d’une seule ressource.","aide":"Cherche la ligne qui parle d’exportations.","type":"zone","document":"fiche","multiple":false},{"enonce":"Que révèle la case « 55 % » ?","aide":"10 % de la population reçoit plus de la moitié du revenu national.","type":"choix","options":[{"id":"a","texte":"Que le PIB par habitant cache une répartition très inégale"},{"id":"b","texte":"Que tous les habitants ont accès à l’éducation"},{"id":"c","texte":"Que le pays n’exporte presque rien à l’étranger"},{"id":"d","texte":"Que l’économie du pays est entièrement tournée vers le tourisme"}],"multiple":false},{"enonce":"Associe chaque indicateur à sa limite.","aide":"Aucun indicateur ne suffit seul : relis ce que chacun mesure.","type":"association","gauche":[{"id":"g0","texte":"PIB par habitant"},{"id":"g1","texte":"IDH"},{"id":"g2","texte":"Stock d’IDE"}],"droite":[{"id":"d0","texte":"Il moyenne les inégalités internes"},{"id":"d1","texte":"Il ignore la répartition des richesses"},{"id":"d2","texte":"Il peut refléter un statut fiscal avantageux"}]},{"enonce":"Petrolia est plutôt…","aide":"Les pays pétroliers sont cités parmi les périphéries intégrées.","type":"choix","options":[{"id":"a","texte":"Une périphérie intégrée : elle fournit des matières premières et en tire une part de la valeur"},{"id":"b","texte":"Une périphérie en marge : elle est presque absente des flux mondiaux"},{"id":"c","texte":"Un territoire isolé : elle n’a aucun échange avec le reste du monde"},{"id":"d","texte":"Un centre d’impulsion : elle concentre les capitaux et l’innovation du monde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"**90 %** des exportations viennent du pétrole et du gaz : Petrolia dépend d’une seule ressource."},{"cle":{"type":"choix","ids":["a"]},"explication":"Quand 10 % des habitants reçoivent **55 %** du revenu, la moyenne du PIB par habitant **cache de fortes inégalités**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le **PIB** ignore la répartition, l’**IDH** moyenne les inégalités, le **stock d’IDE** peut venir d’un statut fiscal avantageux."},{"cle":{"type":"choix","ids":["a"]},"explication":"Petrolia vend des **matières premières** et en capte une part de la valeur : c’est une **périphérie intégrée**."}]$ex$::jsonb),
  ('9df5ab38-8f34-5a9c-b31f-9d3e36b689ce'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"L’enclave et la façade","competence":"analyser-document","situation":"Deux pays voisins imaginaires, Kalia et Nordane, veulent attirer des usines. Zoé croise une note d’investisseur et un tableau pour dire lequel s’intègre le mieux.","documents":[{"id":"note","type":"texte","genre":"article","titre":"Note d’un investisseur","source":"Note imaginée pour l’exercice.","blocs":["Kalia n’a aucun littoral : ses conteneurs passent par le port de Nordane, qui prélève des droits et impose des délais. Un conflit armé ravage sa frontière nord.","Nordane dispose d’un grand port équipé et d’une capitale dotée de banques et de cabinets d’audit. Le pays est stable : les investisseurs étrangers s’y installent."]},{"id":"chiffres","type":"tableau","titre":"Kalia et Nordane","source":"Chiffres inventés pour l’exercice.","colonnes":["","Kalia","Nordane"],"lignes":[["Délai pour exporter un conteneur (jours)","30","10"],["Investissements étrangers reçus (millions de dollars par an)","80","1 200"],["Conflit armé sur le territoire","Oui","Non"]],"enteteLignes":true}],"questions":[{"enonce":"Combien de fois Nordane reçoit-elle plus d’investissements étrangers que Kalia ?","aide":"Divise 1 200 par 80.","type":"nombre","unite":"fois"},{"enonce":"Touche la case qui chiffre le handicap de l’enclavement pour Kalia.","aide":"L’enclavement allonge le trajet des marchandises.","type":"zone","document":"chiffres","multiple":false},{"enonce":"Range chaque élément de la note : il marginalise ou il intègre ?","aide":"Un territoire s’intègre quand il est relié aux flux et rassure ceux qui investissent.","type":"categories","categories":[{"id":"c0","texte":"Marginalise"},{"id":"c1","texte":"Intègre"}],"items":[{"id":"i0","texte":"Un conflit armé à la frontière"},{"id":"i1","texte":"Aucun accès à la mer"},{"id":"i2","texte":"Un port de conteneurs équipé"},{"id":"i3","texte":"Une stabilité qui rassure les investisseurs"},{"id":"i4","texte":"Des banques et des cabinets d’audit dans la capitale"}]},{"enonce":"Quelle conclusion tirer pour Kalia ?","aide":"Voisin d’un pays intégré ne veut pas dire intégré soi-même.","type":"choix","options":[{"id":"a","texte":"Son faible pouvoir d’achat prouve qu’elle est intégrée par ses exportations de services"},{"id":"b","texte":"Sa proximité avec Nordane suffit à en faire un centre d’impulsion de la mondialisation"},{"id":"c","texte":"Son enclavement et son instabilité la laissent en marge, malgré un voisin intégré"},{"id":"d","texte":"Elle deviendra un centre de décision dès que son PIB par habitant aura doublé"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 fois","explication":"1 200 ÷ 80 = **15** : les investisseurs choisissent le pays stable, au port équipé."},{"cle":{"type":"zone","ids":["r0c1"]},"explication":"**30 jours** pour exporter un conteneur, contre 10 à Nordane : sans littoral, Kalia dépend du port de son voisin."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1"}},"explication":"Le port, les services de haut niveau et la stabilité **intègrent** ; l’enclavement et le conflit **marginalisent**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Kalia reste en **marge** : pas de littoral, un conflit, peu d’IDE. Être voisine d’un pays intégré ne suffit pas."}]$ex$::jsonb),
  ('97a6184b-0277-5eb9-956f-fe3032dadea9'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les adresses du pouvoir","competence":"lire-carte","situation":"Sasha trace la carte des lieux de pouvoir du monde : institutions internationales et grands quartiers d’affaires.","documents":[{"id":"carte","type":"carte","titre":"Quatre lieux de pouvoir","source":"Carte schématique.","fond":"monde","cadrage":[-105,5,145,62],"lieux":[{"id":"z1","lieu":"new-york","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"geneve","symbole":"lettre","lettre":"B"},{"id":"z3","lieu":"dubai","symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"shanghai","symbole":"lettre","lettre":"D"}]}],"questions":[{"enonce":"Touche la ville où siège l’ONU.","aide":"C’est une métropole de la côte est des États-Unis.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ville où siègent l’OMC et l’OMS.","aide":"Cette ville est en Suisse.","type":"zone","document":"carte","multiple":false},{"enonce":"Associe chaque quartier d’affaires à sa ville.","aide":"Le cœur d’une ville mondiale s’appelle le CBD.","type":"association","gauche":[{"id":"g0","texte":"Manhattan"},{"id":"g1","texte":"La Défense"},{"id":"g2","texte":"Pudong"},{"id":"g3","texte":"Canary Wharf"}],"droite":[{"id":"d0","texte":"Londres"},{"id":"d1","texte":"Shanghai"},{"id":"d2","texte":"Paris"},{"id":"d3","texte":"New York"}]},{"enonce":"Shanghai et Dubaï gagnent des rangs dans le classement. Que montre ce mouvement ?","aide":"Regarde où se trouvent Shanghai et Dubaï.","type":"choix","options":[{"id":"a","texte":"Que seules les villes d’Europe occidentale commandent l’économie"},{"id":"b","texte":"Que la hiérarchie des villes mondiales évolue avec la montée de l’Asie"},{"id":"c","texte":"Que la hiérarchie des villes mondiales est figée depuis un siècle"},{"id":"d","texte":"Que la taille de la population décide seule du classement"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"L’ONU siège à **New York** (A)."},{"cle":{"type":"zone","ids":["z2"]},"explication":"L’OMC et l’OMS siègent à **Genève** (B)."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"**Manhattan** à New York, **La Défense** à Paris, **Pudong** à Shanghai, **Canary Wharf** à Londres : ce sont des CBD."},{"cle":{"type":"choix","ids":["b"]},"explication":"La hiérarchie est **mouvante** : la montée de l’**Asie** fait gagner des rangs à Shanghai, Shenzhen, Singapour et Dubaï."}]$ex$::jsonb),
  ('97a6184b-0277-5eb9-956f-fe3032dadea9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quand la banque déménage","competence":"analyser-texte","situation":"Une banque imaginaire transfère une partie de ses équipes. Nina lit l’article pour comprendre ce que ce départ dit de la hiérarchie des villes mondiales.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Dans les bureaux de Nordbank","source":"Article imaginé pour l’exercice.","blocs":["Depuis le Brexit, la banque Nordbank a transféré 1 800 de ses 6 000 emplois londoniens vers Francfort, Amsterdam et Paris.","La direction explique que la City reste très attractive, mais qu’il lui faut une entité installée dans l’Union européenne pour continuer à servir ses clients du continent."]}],"questions":[{"enonce":"Touche le mot qui explique le départ d’une partie de l’activité.","aide":"C’est le nom de la sortie du Royaume-Uni de l’Union européenne.","type":"zone","document":"article","multiple":false},{"enonce":"Touche les trois villes qui accueillent les emplois transférés.","aide":"Elles suivent le mot « vers ».","type":"zone","document":"article","multiple":true},{"enonce":"Quelle part des emplois londoniens a été transférée, en pourcentage ?","aide":"Divise 1 800 par 6 000.","type":"nombre","unite":"%"},{"enonce":"Que montre cet exemple de la hiérarchie des villes mondiales ?","aide":"Londres garde des atouts, mais une règle juridique a changé.","type":"choix","options":[{"id":"a","texte":"Qu’elle est fixée une fois pour toutes par les grandes banques"},{"id":"b","texte":"Qu’elle ne change que sous l’effet des catastrophes naturelles"},{"id":"c","texte":"Qu’elle n’est pas acquise : une ville se maintient par son droit et sa stabilité"},{"id":"d","texte":"Qu’elle dépend uniquement de la population des villes concernées"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"Le **Brexit** pousse la banque à installer une entité dans l’Union européenne."},{"cle":{"type":"zone","ids":["m17","m18","m20"]},"explication":"Les emplois vont à **Francfort**, **Amsterdam** et **Paris**."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 %","explication":"1 800 ÷ 6 000 = 0,30, soit **30 %** des emplois."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une ville mondiale se maintient par ses **infrastructures**, son **droit**, ses **talents** et sa **stabilité** : rien n’est acquis."}]$ex$::jsonb),
  ('97a6184b-0277-5eb9-956f-fe3032dadea9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Géante ou connectée ?","competence":"analyser-document","situation":"Deux villes imaginaires, Mégalia et Portalis, se disputent le titre de ville mondiale. Malo les compare en distinguant la hiérarchie du réseau.","documents":[{"id":"villes","type":"tableau","titre":"Mégalia et Portalis","source":"Chiffres inventés pour l’exercice.","colonnes":["","Mégalia","Portalis"],"lignes":[["Habitants (millions)","24","3"],["Sièges de grandes firmes transnationales","4","45"],["Liaisons aériennes directes avec d’autres villes mondiales","12","140"],["Places boursières de rang mondial","0","2"]],"enteteLignes":true},{"id":"rappel","type":"texte","genre":"consigne","titre":"Deux notions","source":"Rappel de cours.","blocs":["La **hiérarchie** dit qui commande à qui. Le **réseau** dit qui est relié à qui."]}],"questions":[{"enonce":"Combien de fois Mégalia compte-t-elle plus d’habitants que Portalis ?","aide":"Divise 24 par 3.","type":"nombre","unite":"fois"},{"enonce":"Touche la case qui montre que Mégalia est peu reliée aux autres villes mondiales.","aide":"Cherche la ligne des liaisons aériennes.","type":"zone","document":"villes","multiple":false},{"enonce":"Range chaque indicateur : il mesure la hiérarchie ou le réseau ?","aide":"Un siège ou une bourse, ce sont des fonctions de commandement ; une liaison relie deux villes.","type":"categories","categories":[{"id":"c0","texte":"Hiérarchie (qui commande)"},{"id":"c1","texte":"Réseau (qui est relié)"}],"items":[{"id":"i0","texte":"Flux de données échangés avec d’autres villes mondiales"},{"id":"i1","texte":"Liaisons aériennes directes"},{"id":"i2","texte":"Places boursières de rang mondial"},{"id":"i3","texte":"Sièges de grandes firmes"}]},{"enonce":"Laquelle de ces villes est une ville mondiale ?","aide":"Une ville mondiale se définit par ses fonctions de commandement, pas par sa taille.","type":"choix","options":[{"id":"a","texte":"Aucune, car il faut dépasser vingt millions d’habitants"},{"id":"b","texte":"Mégalia : elle est de très loin la plus peuplée"},{"id":"c","texte":"Portalis : elle commande et elle est très reliée"},{"id":"d","texte":"Mégalia : elle a une superficie plus étendue"}],"multiple":false},{"enonce":"Complète la définition.","aide":"Relis le tableau : le nombre d’habitants ne décide pas.","type":"trous","segments":["Une ville mondiale se définit par ses ",0," de commandement et non par sa ",1,"."],"banque":["taille","langue","superficie","fonctions"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 fois","explication":"24 ÷ 3 = **8** : Mégalia est bien plus peuplée, mais la taille ne fait pas la ville mondiale."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Seulement **12** liaisons directes, contre 140 pour Portalis : Mégalia est peu connectée."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"**Hiérarchie** : sièges et bourses. **Réseau** : liaisons aériennes et flux de données."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Portalis** cumule commandement (45 sièges, 2 bourses) et connexion (140 liaisons)."},{"cle":{"type":"trous","trous":[["fonctions"],["taille"]]},"affichage":"fonctions · taille","explication":"Une ville mondiale se définit par ses **fonctions** de commandement, pas par sa **taille**."}]$ex$::jsonb),
