   $ex$[{"cle":{"type":"zone","ids":["IDF"]},"explication":"L’**Île-de-France** capte la majorité des sièges sociaux, des IDE et des emplois supérieurs."},{"cle":{"type":"zone","ids":["OCC"]},"explication":"Toulouse est en **Occitanie**, où se concentre l’industrie aéronautique."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Politique** : siège permanent. **Culturel** : francophonie. **Touristique** : première destination mondiale."}]$ex$::jsonb),
  ('e8baade1-ae12-5cbc-a653-e487420131d8'::uuid, 2, 2, 10, 35, 4,
