 mondial n’existe.","type":"choix","options":[{"id":"a","texte":"Ils sont imposés par un gouvernement mondial"},{"id":"b","texte":"Ils reposent sur le consentement des États"},{"id":"c","texte":"Ils ont été votés à l’unanimité par l’OMC"},{"id":"d","texte":"Ils sont appliqués par une police internationale"}],"multiple":false}]}$ex$::jsonb,
